// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp1, uint256 timestamp2, address sender) public {
        // Bound blockNumber to a reasonable range and ensure it's not a multiple of 15
        blockNumber = bound(blockNumber, 1, 1e9);
        vm.assume(blockNumber % 15 != 0);

        // Ensure timestamps are strictly increasing and within a reasonable range
        timestamp1 = bound(timestamp1, 1, 1e12);
        timestamp2 = bound(timestamp2, timestamp1 + 1, 1e12);

        // Exclude precompiles and the contract itself
        vm.assume(sender != address(0) && sender != address(c) && sender.code.length == 0);

        // Give sender enough ether for two calls
        vm.deal(sender, 20 ether);

        // First call: set pastBlockTime to timestamp1 at a block where number % 15 != 0
        vm.roll(blockNumber);
        vm.warp(timestamp1);
        vm.prank(sender);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        require(success1, "First fallback call failed");

        // Second call: timestamp2 > timestamp1, same block where number % 15 != 0
        // The reference contract should NOT transfer entire balance (condition is block.number % 15 == 0)
        // The buggy contract SHOULD transfer entire balance (condition is block.number % 15 != 0)
        // So after the second call, c's balance should be 0 in the buggy version, but 20 ether in the reference
        vm.warp(timestamp2);
        vm.prank(sender);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        require(success2, "Second fallback call failed");

        // General rule: for any block where block.number % 15 != 0, the contract never sends its balance,
        // so after two successful fallback calls, the balance should be exactly 20 ether.
        // The buggy version violates this: it sends balance on != 0, so balance becomes 0.
        assertTrue(address(c).balance == 20 ether);
    }
}

