pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 block1, uint256 block2) public {
        // Restrict blocks to admissible positive integers, block1 < block2 for two distinct calls
        vm.assume(block1 > 0 && block2 > 0);
        vm.assume(block1 < block2);

        // Set up an actor with sufficient ether
        address actor = address(0x1234);
        vm.deal(actor, 20 ether);

        // First call at block1, timestamp = block1 * 12 (ensuring strictly increasing timestamps)
        vm.roll(block1);
        vm.warp(block1 * 12);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        uint256 pastBlockTimeAfterFirst = c.pastBlockTime();

        // Second call at block2, timestamp = block2 * 12
        vm.roll(block2);
        vm.warp(block2 * 12);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        uint256 pastBlockTimeAfterSecond = c.pastBlockTime();

        // General rule: pastBlockTime after second call MUST be strictly greater than after first call
        assertTrue(pastBlockTimeAfterSecond > pastBlockTimeAfterFirst);
    }
}

