pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bool divisibleBy15) public {
        // 1. Restrict amount to a wide admissible range: from 1 wei up to 100 ether.
        vm.assume(amount >= 1 && amount <= 100 ether);

        // 2. Set block.number to a value that matches the divisibleBy15 condition.
        //    This avoids violating the block.timestamp requirement and lets us explore both branches.
        uint256 blockNum = divisibleBy15 ? 15 : 16;
        vm.roll(blockNum);
        vm.warp(1); // ensure block.timestamp > pastBlockTime (initially 0)

        // Deploy a helper that receives ether without reverting, since a simple EOA call always succeeds.
        Helper helper = new Helper();

        // Fund and call the contract through the helper.
        vm.deal(address(helper), amount);
        vm.prank(address(helper));
        (bool success,) = address(c).call{value: amount}("");

        // 3. Assert: For the reference contract, after any successful fallback call the contract's balance is always zero.
        //    The buggy contract can have a non-zero balance when amount != 10 ether and block.number % 15 != 0.
        assertTrue(!success || address(c).balance == 0);
    }
}

contract Helper {
    fallback() external payable {}
}

