pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp, uint256 past, address caller) public {
        vm.assume(blockNum > 0);
        vm.assume(timestamp > past);
        vm.assume(caller != address(0) && caller != address(c));
        vm.roll(blockNum);
        vm.warp(past);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "initial call failed");

        vm.warp(timestamp);
        vm.roll(blockNum);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        require(ok2, "test call failed");

        if (blockNum % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance >= 10 ether);
        }
    }
}

